package cn.workbench;

import org.springframework.web.bind.annotation.*;
import org.springframework.http.*;
import org.springframework.beans.factory.annotation.Value;
import jakarta.servlet.http.HttpServletRequest;
import java.util.*;
import java.util.concurrent.*;
import java.time.*;
import java.nio.charset.StandardCharsets;

@RestController @RequestMapping("/api/v1")
public class StatsController {
 final TaskService tasks;final Policy p;final Writes w;final KpiController kpi;final Records r;final String exportFont;final DashboardSummary dashboard;
 final ConcurrentMap<Long,Long> lastExport=new ConcurrentHashMap<>();final Semaphore exportSlots=new Semaphore(2);
 public StatsController(TaskService t,Policy p,Writes w,KpiController k,Records r,DashboardSummary dashboard,@Value("${task.export-font:}")String font){tasks=t;this.p=p;this.w=w;kpi=k;this.r=r;this.dashboard=dashboard;exportFont=font;}
 @GetMapping("/stats/overview") Object overview(HttpServletRequest q,@RequestParam(defaultValue="all")String focus){if(!Set.of("all","attention","active").contains(focus))throw TaskService.invalid("任务筛选无效");var actor=p.actor(q);var list=tasks.tasks(actor);Instant now=Instant.now();var summaries=list.stream().map(task->{var result=new LinkedHashMap<>(task);result.putAll(dashboard.signals(actor,task,now));return (Map<String,Object>)result;}).filter(task->!focus.equals("attention")||Jsons.integer(task.get("attentionRank"))<4).filter(task->!focus.equals("active")||Set.of("IN_PROGRESS","REWORK").contains(task.get("status"))).sorted(Comparator.comparingInt((Map<String,Object> task)->Jsons.integer(task.get("attentionRank"))).thenComparing(task->Records.instant(task.get("deadline")))).limit(5).map(task->dashboard.enrich(actor,task,task)).toList();return Api.ok(Records.map("total",list.size(),"inProgress",list.stream().filter(x->Set.of("IN_PROGRESS","REWORK").contains(x.get("status"))).count(),"pendingAcceptance",list.stream().filter(x->Set.of("PENDING_ACCEPTANCE","PENDING_ACCEPTANCE_WITH_GAP").contains(x.get("status"))).count(),"overdue",list.stream().filter(StatsController::overdue).count(),"completed",list.stream().filter(x->x.get("status").equals("COMPLETED")).count(),"recentTasks",summaries));}
 static boolean overdue(Map<String,Object> t){return overdueAt(t,Instant.now());}
 static boolean overdueAt(Map<String,Object> t,Instant now){if(Boolean.TRUE.equals(t.get("everOverdue")))return true;if(t.get("deadline")==null)return false;Instant deadline=Records.instant(t.get("deadline"));Object completed=t.get("submittedAt")!=null?t.get("submittedAt"):t.get("summarizedAt");if(completed!=null)return Records.instant(completed).isAfter(deadline);return !Set.of("COMPLETED","ACCEPTED","CANCELLED").contains(t.get("status"))&&deadline.isBefore(now);}
 static boolean inRange(Map<String,Object> record,String from,String to){Instant time=Records.instant(record.get("createdAt"));try{return (from==null||!time.isBefore(LocalDate.parse(from).atStartOfDay(ZoneId.of("Asia/Shanghai")).toInstant()))&&(to==null||time.isBefore(LocalDate.parse(to).plusDays(1).atStartOfDay(ZoneId.of("Asia/Shanghai")).toInstant()));}catch(Exception e){throw TaskService.invalid("日期格式应为YYYY-MM-DD");}}
 @GetMapping("/stats/dept") Object departments(HttpServletRequest q,@RequestParam(required=false)String from,@RequestParam(required=false)String to){var a=p.actor(q);if(!a.reportReader())throw ApiException.denied();List<Map<String,Object>> result=new ArrayList<>();for(var d:r.list("DEPARTMENT",a.company(),null)){if(!a.leader()&&!a.globalAdmin()&&!Objects.equals(a.dept(),Jsons.integer(d.get("id"))))continue;var subs=r.list("SUB_TASK",Jsons.integer(d.get("companyId")),Jsons.integer(d.get("id"))).stream().filter(s->{var task=r.get(Jsons.number(s.get("taskId")));return !"DRAFT".equals(task.get("status"))&&p.canSeeTask(a,task)&&inRange(s,from,to);}).toList();long completed=subs.stream().filter(s->s.get("status").equals("ACCEPTED")).count();result.add(Records.map("deptId",d.get("id"),"deptName",d.get("name"),"total",subs.size(),"completed",completed,"submitted",subs.stream().filter(s->s.get("status").equals("SUBMITTED")).count(),"inProgress",subs.stream().filter(s->Set.of("IN_PROGRESS","REWORK").contains(s.get("status"))).count(),"overdue",subs.stream().filter(StatsController::overdue).count(),"completionRate",subs.isEmpty()?null:java.math.BigDecimal.valueOf(100*completed).divide(java.math.BigDecimal.valueOf(subs.size()),2,java.math.RoundingMode.HALF_UP)));}return Api.ok(result);}
 @GetMapping("/stats/export") ResponseEntity<byte[]> export(HttpServletRequest q,@RequestParam(defaultValue="xlsx")String format,@RequestParam(required=false)String from,@RequestParam(required=false)String to){var a=p.actor(q);if(!a.reportReader())throw ApiException.denied();p.freshTotp(q);return bounded(a,()->{var snapshot=tasks.tasks(a).stream().filter(t->inRange(t,from,to)).toList();var rows=snapshot.stream().map(t->List.of(value(t,"code"),value(t,"title"),value(t,"status"),value(t,"deadline"),value(t,"everOverdue"))).toList();var result=document(a,"tasks",format,List.of("编号","标题","状态","截止时间","曾经逾期"),rows);w.audit(a,"TASK_EXPORT_"+format.toUpperCase(Locale.ROOT),0);return result;});}
 @GetMapping("/kpi/export") ResponseEntity<byte[]> exportKpi(HttpServletRequest q,@RequestParam(required=false)String period,@RequestParam(required=false)Integer companyId,@RequestParam(defaultValue="xlsx")String format){var a=p.actor(q);p.freshTotp(q);return bounded(a,()->{var snapshot=kpi.scoresData(a,period,companyId);var rows=snapshot.stream().map(s->List.of(value(s,"period"),value(s,"departmentName"),score(s,"rawScore"),s.get("adjustedScore")==null?"":value(s,"adjustedScore"),score(s,"finalScore"),value(s,"status"),value(s,"runId"),value(s,"templateVersion"))).toList();var result=document(a,"kpi",format,List.of("期间","部门","原始分","调整分","最终分","状态","计算批次","模板版本"),rows);w.audit(a,"KPI_EXPORT_"+format.toUpperCase(Locale.ROOT),0);return result;});}
 ResponseEntity<byte[]> bounded(Policy.Actor a,java.util.function.Supplier<ResponseEntity<byte[]>> body){long now=System.currentTimeMillis();Long previous=lastExport.putIfAbsent(a.uid(),now);if(previous!=null){if(now-previous<2000||!lastExport.replace(a.uid(),previous,now))throw new ApiException(429,"EXPORT_RATE_LIMIT","导出过于频繁，请稍后重试");}if(!exportSlots.tryAcquire())throw new ApiException(429,"EXPORT_BUSY","导出繁忙，请稍后重试");try{return body.get();}finally{exportSlots.release();}}
 static String value(Map<String,Object> m,String key){return m.get(key)==null?"":m.get(key).toString();}static String score(Map<String,Object>s,String key){return s.get(key)==null?"N/A":s.get(key).toString();}
 ResponseEntity<byte[]> document(Policy.Actor a,String name,String format,List<String> headers,List<List<String>> rows){ExportFormats.validate(rows);String watermark="Internal | actor="+a.uid()+" | scope="+a.scopeId()+" | "+Instant.now();byte[] bytes;String mime;switch(format){case "xlsx"->{bytes=ExportFormats.xlsx(watermark,headers,rows);mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";}case "pdf"->{bytes=ExportFormats.pdf(watermark,headers,rows,exportFont);mime="application/pdf";}case "csv"->{var out=new StringBuilder("\ufeff").append(Domain.csv(watermark)).append("\r\n");out.append(String.join(",",headers.stream().map(Domain::csv).toList())).append("\r\n");for(var row:rows)out.append(String.join(",",row.stream().map(Domain::csv).toList())).append("\r\n");bytes=out.toString().getBytes(StandardCharsets.UTF_8);mime="text/csv;charset=UTF-8";}default->throw TaskService.invalid("导出格式应为xlsx/pdf/csv");}return ResponseEntity.ok().header("Cache-Control","no-store").header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+name+"."+format+"\"").contentType(MediaType.parseMediaType(mime)).body(bytes);}
}
